  color: #5a6463;
}

.search select,
.search input {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 8px 10px;
  border: 1px solid #8a9491;
  border-radius: 6px;
  background: #ffffff;
  font: inherit;
  font-size: 16px;
  color: #26302f;
}

.search button {
  width: 100%;
  margin-top: 6px;
  padding: 11px;
  border: 0;
  border-radius: 6px;
  background: #2d5d5a;
  color: #ffffff;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}

.routes {
  margin-top: 48px;
}

h2 {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 500;
}

.routes ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.routes li {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
  border-top: 1px solid #dfe3e0;
  color: #5a6463;
}

.routes li:last-child {
  border-bottom: 1px solid #dfe3e0;
}

.route-name {
  color: #26302f;
}

.route-facts {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* Tablet: stack the form under the text so the lead keeps a readable line length. */
@media (max-width: 900px) {
  .hero {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }

  /* "display: contents" removes the text column's own box, so its children become items of the
     hero column. That lets "order" put the form between the intro text and the routes. */
  .hero-text {
    display: contents;
  }

  .hero-text > * {
    max-width: 640px;
  }

  .text-link {
    align-self: flex-start;
    margin-bottom: 32px;
  }

  .search {
    order: 1;
    flex: none;
  }

  .routes {
    order: 2;
  }
}

/* Phone: logo above a single row of nav links, smaller headline, narrower page margins. */
@media (max-width: 560px) {
  .site-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    padding: 18px 20px 8px;
  }

  .site-nav {
    flex-wrap: wrap;
    gap: 6px 20px;
  }

  .site-nav a {
    font-size: 15px;
  }

  .hero {
    padding: 32px 20px 48px;
  }

  h1 {
    font-size: 32px;
  }

  .lead {
    font-size: 17px;
  }

  .search {
    padding: 20px;
  }
}
